import type { SQLiteDatabase } from "expo-sqlite";

// Generated by scripts/csv-to-history.ts and gitignored. If it's missing the
// app won't build: run the script (on fixtures/history.sample.csv for a fresh clone).
import history from "../../data/history.json";
import type { ImportRow } from "./dailyEntries";
import { migrate } from "./migrations";
import { seedHistoryOnce } from "./seedHistory";

// SQLiteProvider onInit: runs before any screen renders.
export async function initDb(db: SQLiteDatabase): Promise<void> {
  await migrate(db);
  await seedHistoryOnce(db, history.rows as ImportRow[]);
}
